ROOT=Path(__file__).resolve().parents[2];DATA=prior.DATA;META=prior.META
read=prior.read;pin=prior.pin;identity=prior.identity;encoded=prior.encoded;require=prior.require
FOLDER='docs/literature/velocyto-catalog-admission';ROLES='docs/literature/velocyto-source-audit/ROLES.json';Q='docs/literature/velocyto-validation/QUALIFICATION.json'
COVERAGE=DATA+'/velocyto-source-role-coverage.json';PROOF=DATA+'/velocyto-catalog-validation.json';SOURCE='src/main/java/org/jlinalg/cli/VelocytoToolsCli.java'
REVIEWED='individually-reviewed-primary-source-roles; whole-paper-method-review-open'
SCOPE='Original velocyto0.17.17 CB/UB droplet spliced/unspliced/ambiguous counts from actual coordinate-sorted BAMs and compatible GTF, with Default/Permissive10X logic, supplied or original-inferred barcodes, explicit multimapper handling and distinct-cell BAM batches. Native Java literal MA-to-UB/declared-contig preparation, complete input molecule bounds and all-value Loom count audits export exact S+U separately from original float32(S+U+A). Original CLI uint16 buffers require proven safety; explicit original Counter API uint64 is a different integer profile. Complete source/runtime/JAR/input binding and fresh replay are required. RNA velocities, scVelo/PAGA, Smartseq, other logics, incomplete repeat masks, unknown author modifications, exact author recipes and whole-paper reproduction remain separate.'
